update t_apig_apis
set NAME                    = #{apigApisDto.name},
    LAST_UPDATED_BY_USER_ID = #{apigApisDto.lastUpdatedByUserId},
    LAST_UPDATED_DATE       = #{apigApisDto.lastUpdatedDate}
where ID = #{apigApisDto.id};

update t_apig_apis
set dept_code = #{deptCode}
where dept_code is null
  and created_by_user_id = #{userId}
